// Baut den SMS-Text aus einer Vorlage der Kunden-Config. Der Agent liefert nur
// Werte, nie den fertigen Text - so kann er den Inhalt nicht frei bestimmen.
const e = $input.first().json;
const p = e.params || {};
const c = e.config || {};

// Rufnummern kommen in vielen Schreibweisen. Verglichen wird ueber die
// letzten neun Ziffern - das trifft 0170…, +49170… und 0049170… gleich.
function normTelefon(t) {
  let s = String(t || '').trim().replace(/[^0-9+]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (s.startsWith('0')) s = '+49' + s.slice(1);
  return s;
}
function ziffern(t) { return String(t || '').replace(/[^0-9]/g, '').slice(-9); }

const an = normTelefon(p.telefon || e.from_number);
const vorlagen = (c.sms_vorlagen && typeof c.sms_vorlagen === 'object') ? c.sms_vorlagen : {};
const schluessel = String(p.textvorlage || '').trim();

// hasOwnProperty, damit "toString" oder "constructor" keine Prototyp-Funktion
// als Vorlage durchreichen.
let text = Object.prototype.hasOwnProperty.call(vorlagen, schluessel)
  ? String(vorlagen[schluessel] || '') : '';

const werte = (p.werte && typeof p.werte === 'object') ? p.werte : {};
if (text) {
  // Platzhalter {{name}} serverseitig fuellen; unbekannte Platzhalter werden geleert.
  text = text.replace(/{{\s*([a-zA-Z0-9_]+)\s*}}/g, (_, k) => {
    const v = werte[k];
    return v === undefined || v === null ? '' : String(v).slice(0, 200);
  }).trim();
}

// Zielnummern-Allowlist: ohne sie koennte ein manipuliertes Gespraech SMS an
// beliebige Nummern weltweit ausloesen - auf Rechnung des Kunden.
const prefixe = Array.isArray(c.sms_prefixe) && c.sms_prefixe.length ? c.sms_prefixe : ['+49'];
const erlaubt = prefixe.some(pre => an.startsWith(String(pre)));

let fehler = '';
if (!c.sms_from) fehler = 'keine absendernummer konfiguriert';
else if (!c.twilio_account_sid) fehler = 'twilio nicht konfiguriert';
else if (!an || an.length < 8) fehler = 'zielnummer fehlt oder ungueltig';
else if (!erlaubt) fehler = 'zielnummer nicht erlaubt';
else if (!schluessel) fehler = 'textvorlage fehlt';
else if (!text) fehler = 'textvorlage unbekannt';

return [{ json: Object.assign({}, e, {
  an: an, text: text.slice(0, 600), fehler: fehler,
}) }];

const ktx = $('Eingaben pruefen').first().json;
// Vereinheitlicht die Antwort. Kein Sub-Workflow gibt je etwas anderes
// zurueck als { success, data, message } - darauf bauen die Retell-Agenten
// ihre Erfolgs- und Fehlerzweige auf.
function antwort(success, data, message) {
  return { success: !!success, data: data || {}, message: String(message || '') };
}

if (ktx.fehler) return [{ json: antwort(false, { gesendet: false }, ktx.fehler) }];

const r = $input.first().json || {};
if (r.error) return [{ json: antwort(false, { gesendet: false }, 'sms-dienst nicht erreichbar') }];

const code = Number(r.statusCode);
if (code === 401 || code === 403 || code === 404) {
  // Typischer Fall: twilio_account_sid in der Config passt nicht zum Credential.
  return [{ json: antwort(false, { gesendet: false, code: code },
    'sms-konto passt nicht zur konfiguration') }];
}
if (code >= 400) {
  return [{ json: antwort(false, { gesendet: false, code: code }, 'sms fehlgeschlagen') }];
}
const b = r.body || {};
return [{ json: antwort(true, { gesendet: true, sid: String(b.sid || ''),
  status: String(b.status || '') }, 'sms verschickt') }];
